mutations.before:
const rewritten = rewriteBriefRefs(files.brief, scanned.slug, refToId);
const stored = await briefs.findBriefById(scanned.slug);
if (dumpBrief(rewritten) === dumpBrief((stored as StoredBrief).brief))
  return { kind: "unchanged" };

mutations.after:
const stored = await briefs.findBriefById(scanned.slug);
if (dumpBrief(files.brief) === dumpBrief((stored as StoredBrief).brief))
  return { kind: "unchanged" };

mutations.before:
if (isExistsError(error)) {
  return {
    outcome: "refused",
    reason: "refused: slug reserved",
    minted: { assets: [] },
    unreferencedInputs: unreferenced,
  };
}

if (!isAssetId(ref)) {
  throw new Error(`ref survived rewrite as a path, not an asset id: ${ref}`);
}

if (UUID_PATTERN.test(scanned.slug)) {
  return { ok: false, reason: `a uuid-shaped slug is refused: ${scanned.slug}` };
}
